package com.crm.customer;
import com.crm.customer.config.SecurityConfig;import com.crm.customer.controller.ContactWorkController;import com.crm.customer.service.*;import com.crm.customer.exception.GlobalExceptionHandler;import com.crm.security.*;import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;import org.springframework.context.annotation.*;import org.springframework.mock.web.MockServletContext;import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;import org.springframework.web.servlet.config.annotation.EnableWebMvc;import org.springframework.test.web.servlet.MockMvc;import java.time.Instant;import java.util.List;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
/** Real security chain/MVC, mocked Identity and domain services; no network/base. */
class CommercialSecurityTest {AnnotationConfigWebApplicationContext context;MockMvc mvc;AccountValidationClient validation;AssignedContactService assigned;ClientCaseService cases;
 @Configuration @EnableWebMvc static class Beans {@Bean jakarta.persistence.EntityManagerFactory entityManagerFactory(){return mock(jakarta.persistence.EntityManagerFactory.class);}@Bean AccountValidationClient validation(){return mock(AccountValidationClient.class);}@Bean JwtAuthenticationFilter jwt(AccountValidationClient c){return new JwtAuthenticationFilter(c);}@Bean RestAuthenticationEntryPoint entry(){return new RestAuthenticationEntryPoint();}@Bean CustomAccessDeniedHandler denied(){return new CustomAccessDeniedHandler();}@Bean AssignedContactService assigned(){return mock(AssignedContactService.class);}@Bean ClientCaseService cases(){return mock(ClientCaseService.class);}@Bean ContactWorkController controller(AssignedContactService a,ClientCaseService c){return new ContactWorkController(a,c);}@Bean GlobalExceptionHandler errors(){return new GlobalExceptionHandler();}}
 @BeforeEach void setup(){context=new AnnotationConfigWebApplicationContext();context.setServletContext(new MockServletContext());context.register(Beans.class,SecurityConfig.class);context.refresh();validation=context.getBean(AccountValidationClient.class);assigned=context.getBean(AssignedContactService.class);cases=context.getBean(ClientCaseService.class);mvc=webAppContextSetup(context).addFilters(context.getBean("springSecurityFilterChain",jakarta.servlet.Filter.class)).build();}@AfterEach void close(){context.close();org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 void role(String role){when(validation.validate(any())).thenReturn(new AccountValidationResult(AccountValidationResult.Status.VALID,new JwtService.AccessTokenClaims(42,"synthetic",List.of(role),Instant.now().plusSeconds(3600))));}
 @ParameterizedTest @ValueSource(strings={"EMPLOYEE","CLIENT","ADMIN","SUPER_ADMIN"}) void eachNamespaceHasItsOwnRbac(String role)throws Exception{role(role);boolean employee=role.equals("EMPLOYEE"),client=role.equals("CLIENT"),admin=role.equals("ADMIN")||role.equals("SUPER_ADMIN");for(String path:List.of("/assigned","/assigned/7","/assigned/7/interactions"))mvc.perform(get("/api/contact-work"+path).header("Authorization","Bearer synthetic")).andExpect(status().is(employee?200:403));for(String path:List.of("/cases","/cases/9","/cases/9/messages","/cases/9/history")){mvc.perform(get("/api/contact-work/client"+path)).andExpect(status().is(client?200:403));mvc.perform(get("/api/contact-work/admin"+path)).andExpect(status().is(admin?200:403));}if(!employee)verifyNoInteractions(assigned);if(employee)verifyNoInteractions(cases);}
 @ParameterizedTest @ValueSource(strings={"EMPLOYEE","CLIENT","ADMIN","SUPER_ADMIN"}) void writesDoNotCrossNamespaces(String role)throws Exception{role(role);mvc.perform(put("/api/contact-work/assigned/7").header("Authorization","Bearer synthetic").contentType("application/json").content("{\"email\":\"test@example.invalid\"}")).andExpect(status().is(role.equals("EMPLOYEE")?200:403));mvc.perform(post("/api/contact-work/client/cases").contentType("application/json").content("{\"requestId\":\"00000000-0000-0000-0000-000000000001\",\"subject\":\"Subject\",\"description\":\"Body\"}")).andExpect(status().is(role.equals("CLIENT")?200:403));mvc.perform(patch("/api/contact-work/admin/cases/9/status").contentType("application/json").content("{\"status\":\"RESOLVED\"}")).andExpect(status().is(role.equals("ADMIN")||role.equals("SUPER_ADMIN")?200:403));}
 @Test void missingAndUnavailableIdentityFailClosed()throws Exception{when(validation.validate(any())).thenReturn(AccountValidationResult.invalid());mvc.perform(get("/api/contact-work/client/cases")).andExpect(status().isUnauthorized());when(validation.validate(any())).thenReturn(AccountValidationResult.unavailable());mvc.perform(get("/api/contact-work/client/cases")).andExpect(status().isServiceUnavailable());verifyNoInteractions(assigned,cases);}
 @Test void personalTargetingParametersAreRefusedBeforeDomainCall()throws Exception{role("EMPLOYEE");mvc.perform(get("/api/contact-work/assigned?employeeId=102").header("Authorization","Bearer synthetic")).andExpect(status().isBadRequest());role("CLIENT");mvc.perform(get("/api/contact-work/client/cases?customerId=8")).andExpect(status().isBadRequest());verifyNoInteractions(assigned,cases);}
 @Test void noStoreAndInvalidInputsAreExplicit()throws Exception{role("CLIENT");mvc.perform(get("/api/contact-work/client/cases")).andExpect(header().string("Cache-Control","no-store"));mvc.perform(post("/api/contact-work/client/cases").contentType("application/json").content("{\"requestId\":\"bad\",\"subject\":\"\",\"description\":\"Body\"}")).andExpect(status().isBadRequest());mvc.perform(get("/api/contact-work/client/cases?page=bad")).andExpect(status().isBadRequest());verify(cases,times(1)).list(false,null,0);verifyNoMoreInteractions(cases);}
 @Test void remoteFailuresPreserveCodeWithoutPrivateBody()throws Exception{role("EMPLOYEE");for(int code:List.of(401,403,404,409,502,503)){doThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.valueOf(code),"synthetic-private")).when(assigned).list(any(),any(),anyInt());mvc.perform(get("/api/contact-work/assigned").header("Authorization","Bearer synthetic")).andExpect(status().is(code)).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("synthetic-private"))));}}
}
